// LoadPro allows an eager lookup of values, cached into the
// loaded structs of the objects. This is for an N-1 relationship.
func (contratoL) LoadPro(ctx context.Context, e boil.ContextExecutor, singular bool, maybeContrato interface{}, mods queries.Applicator) error {
	var slice []*Contrato
	var object *Contrato

	if singular {
		var ok bool
		object, ok = maybeContrato.(*Contrato)
		if !ok {
			object = new(Contrato)
			ok = queries.SetFromEmbeddedStruct(&object, &maybeContrato)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybeContrato))
			}
		}
	} else {
		s, ok := maybeContrato.(*[]*Contrato)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybeContrato)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybeContrato))
			}
		}
	}

	args := make(map[interface{}]struct{})
	if singular {
		if object.R == nil {
			object.R = &contratoR{}
		}
		args[object.ProID] = struct{}{}

	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &contratoR{}
			}

			args[obj.ProID] = struct{}{}

		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]interface{}, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`produto`),
		qm.WhereIn(`produto.pro_id in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load Produto")
	}

	var resultSlice []*Produto
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice Produto")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results of eager load for produto")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for produto")
	}

	if len(produtoAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}

	if len(resultSlice) == 0 {
		return nil
	}

	if singular {
		foreign := resultSlice[0]
		object.R.Pro = foreign
		if foreign.R == nil {
			foreign.R = &produtoR{}
		}
		foreign.R.ProContratos = append(foreign.R.ProContratos, object)
		return nil
	}

	for _, local := range slice {
		for _, foreign := range resultSlice {
			if local.ProID == foreign.ProID {
				local.R.Pro = foreign
				if foreign.R == nil {
					foreign.R = &produtoR{}
				}
				foreign.R.ProContratos = append(foreign.R.ProContratos, local)
				break
			}
		}
	}

	return nil
}

