// RemoveOrc relationship.
// Sets o.R.Orc to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Contrato) RemoveOrc(ctx context.Context, exec boil.ContextExecutor, related *OrcamentoCompra) error {
	var err error

	queries.SetScanner(&o.OrcID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("orc_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Orc = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.OrcContratos {
		if queries.Equal(o.OrcID, ri.OrcID) {
			continue
		}

		ln := len(related.R.OrcContratos)
		if ln > 1 && i < ln-1 {
			related.R.OrcContratos[i] = related.R.OrcContratos[ln-1]
		}
		related.R.OrcContratos = related.R.OrcContratos[:ln-1]
		break
	}
	return nil
}

